python3 << 'PYEOF'
import json, re

with open('/home/ubuntu/.claude-account-4/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-9-projects-event-gated-adaptive-horizon/1eaefe44-d2f8-4520-8dc9-47bed9b0d6cf/tool-results/mcp-agent-ml-research-read_registry-1779878832216.txt', 'r') as f:
    data = json.load(f)

parsed = json.loads(data['result'])
experiments = parsed['data']['experiments']
walker_cheetah = {k: v for k, v in experiments.items() if 'walker' in k.lower() or 'cheetah' in k.lower()}

def get_nve_peak(m):
    """Extract NVE peak from metrics, trying various key names."""
    # Direct nve_peak keys (case variations)
    for key in ['nve_peak', 'NVE_peak', 'NVE', 'civo_nve_peak']:
        if key in m and m[key] is not None:
            v = m[key]
            if isinstance(v, (int, float)):
                return v

    # ve_ratio_peak
    for key in ['ve_ratio_peak', 'nve_peak_value']:
        if key in m and m[key] is not None:
            v = m[key]
            if isinstance(v, (int, float)):
                return v

    # nve at specific steps (take the max)
    nve_vals = []
    for key, val in m.items():
        if isinstance(val, (int, float)):
            k_lower = key.lower()
            if k_lower.startswith('nve_') and any(c.isdigit() for c in k_lower):
                nve_vals.append(val)
            elif k_lower == 'nve_final' or k_lower == 'nve_105k':
                nve_vals.append(val)
    if nve_vals:
        return max(nve_vals)

    # NVE_final
    for key in ['NVE_final', 'nve_final']:
        if key in m and m[key] is not None and isinstance(m[key], (int, float)):
            return m[key]

    return None

def get_eval_pct_baseline(m):
    """Extract eval as percentage of baseline."""
    for key in ['eval_final_pct_baseline', 'eval_pct_baseline', 'baseline_pct',
                'eval_pct', 'eval_return_pct_baseline', 'pct_baseline']:
        if key in m and m[key] is not None and isinstance(m[key], (int, float)):
            return m[key]
    return None

def classify_experiment_type(exp_id, hypothesis):
    """Classify experiment: 'trained', 'frozen', 'no_dt_emb', 'baseline', 'unexposed', 'other'"""
    eid = exp_id.lower()
    hyp = (hypothesis or '').lower()

    if 'baseline' in eid:
        return 'baseline'
    if 'no_dt_emb' in eid or 'no_dt_embed' in eid:
        return 'no_dt_emb'
    if 'frozen' in eid or 'frozen_dt_emb' in eid:
        return 'frozen'
    if 'unexposed' in eid:
        return 'unexposed'

    # Check hypothesis
    if 'baseline' in hyp and 'no dt' not in hyp and 'frozen' not in hyp:
        if 'trained' not in hyp:
            return 'baseline'
    if 'no_dt_emb' in hyp or 'no dt_emb' in hyp or 'without dt' in hyp:
        return 'no_dt_emb'
    if 'frozen dt' in hyp or 'frozen_dt' in hyp:
        return 'frozen'
    if 'unexposed' in hyp:
        return 'unexposed'

    # 008d, 008e, 010b, civo_trigger = trained dt_emb with subsample
    if '008d' in eid or '008e' in eid or 'civo_trigger' in eid:
        return 'trained'
    if '008a' in eid:
        return 'unexposed'
    if '008f' in eid:
        return 'no_dt_emb'

    # Check for trained dt_emb in hypothesis
    if 'trained dt_emb' in hyp or 'trained_dt_emb' in hyp or 'subsample on' in hyp.replace('=', ' '):
        return 'trained'

    # SGS, TCN, RAVE, dual_critic, wide_critic, narrow, gradient_stop are all interventions
    for pattern in ['sgs', 'tcn', 'rave', 'dual_critic', 'wide_critic', 'narrow_dual', 'gradient_stop']:
        if pattern in eid:
            return 'intervention'

    return 'unknown'

def get_ground_truth(exp_type, eval_pct, conclusion, hypothesis):
    """
    Ground Truth:
    - True CIVO: trained dt_emb experiment where eval < 50% baseline and shows CIVO pattern
    - No CIVO: baseline/frozen/no_dt_emb/unexposed experiments, or trained with eval > 70%
    - Ambiguous: everything else (excluded from analysis)
    """
    concl = (conclusion or '').lower()
    hyp = (hypothesis or '').lower()

    # baseline/frozen/no_dt_emb/unexposed = No CIVO by design
    if exp_type in ['baseline', 'frozen', 'no_dt_emb', 'unexposed']:
        return 'no_civo'

    # trained experiments
    if exp_type == 'trained':
        if eval_pct is not None:
            if eval_pct < 50:
                return 'civo'
            elif eval_pct > 70:
                return 'no_civo'
        # Check conclusion
        if 'civo' in concl and ('collapse' in concl or 'confirmed' in concl or 'fail' in concl):
            return 'civo'
        if concl == 'success' and ('healthy' in concl or 'no civo' in concl):
            return 'no_civo'
        # If conclusion says success and hypothesis is about CIVO trigger
        if 'civo_trigger' in hyp or 'civo trigger' in hyp:
            if 'success' in concl:
                return 'civo'  # CIVO trigger experiment that succeeded = CIVO was triggered
        return 'ambiguous'

    # intervention experiments (SGS, TCN, etc.) - designed to prevent CIVO
    if exp_type == 'intervention':
        return 'intervention'

    return 'ambiguous'

# Process all experiments
results = []
for exp_id in sorted(walker_cheetah.keys()):
    v = walker_cheetah[exp_id]
    m = v.get('metrics', {}) or {}
    status = v.get('status', '')
    conclusion = v.get('conclusion', '') or ''
    hypothesis = v.get('hypothesis', '') or ''

    if status not in ['DONE', 'COMPLETED']:
        continue

    exp_type = classify_experiment_type(exp_id, hypothesis)
    nve_peak = get_nve_peak(m)
    eval_pct = get_eval_pct_baseline(m)
    ground_truth = get_ground_truth(exp_type, eval_pct, conclusion, hypothesis)

    results.append({
        'exp_id': exp_id,
        'exp_type': exp_type,
        'nve_peak': nve_peak,
        'eval_pct': eval_pct,
        'ground_truth': ground_truth,
        'conclusion': conclusion[:60],
        'status': status
    })

# Report
print(f"Total Walker/Cheetah experiments (DONE): {len(results)}")
print(f"\nBy type:")
from collections import Counter
type_counts = Counter(r['exp_type'] for r in results)
for t, c in sorted(type_counts.items()):
    print(f"  {t}: {c}")

print(f"\nBy ground truth:")
gt_counts = Counter(r['ground_truth'] for r in results)
for g, c in sorted(gt_counts.items()):
    print(f"  {g}: {c}")

# Show experiments with valid NVE peak and clear ground truth
valid = [r for r in results if r['nve_peak'] is not None and r['ground_truth'] in ('civo', 'no_civo')]
print(f"\nUsable for analysis (has NVE peak + clear ground truth): {len(valid)}")
print(f"  CIVO: {sum(1 for r in valid if r['ground_truth'] == 'civo')}")
print(f"  No CIVO: {sum(1 for r in valid if r['ground_truth'] == 'no_civo')}")

print("\n=== CIVO experiments ===")
for r in valid:
    if r['ground_truth'] == 'civo':
        print(f"  {r['exp_id']}: NVE={r['nve_peak']:.3f}, eval_pct={r['eval_pct']}, concl={r['conclusion']}")

print("\n=== No CIVO experiments ===")
for r in valid:
    if r['ground_truth'] == 'no_civo':
        print(f"  {r['exp_id']}: type={r['exp_type']}, NVE={r['nve_peak']:.3f}, eval_pct={r['eval_pct']}, concl={r['conclusion']}")
PYEOF

